def has_close_elements(numbers: List[float], threshold: float) -> bool:
    sorted_numbers = sorted(numbers + [-np.inf, np.inf])
    return any(abs(sorted_numbers[i] - sorted_numbers[i+1]) < threshold for i in range(len(sorted_numbers) - 1))

def find_topmost_carpet(n, carpets, point):
    mns, ms = [], []
    for m in carpets:
        mn, ms = [*mn, min(m[0], point[0])], [*ms, max(m[1], point[1])]
    if mn and point[0] == mn[-1]:
        return -1
    return len(mns) - mns.index(point[0])

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    max_path_sum = [0] * N
    paths = [[0] * N for _ in range(N)]

    # Populate max_path_sum and paths
    for y in range(N):
        for x in range(N):
            if y == 0 and x == 0:
                max_path_sum[x] = grid_values[y][2]
                paths[y][x] = (0, 0)
            elif y == 0:
                max_path_sum[x] = max_path_sum[x-1] + grid_values[y][2]
                paths[y][x] = (paths[y-1][x], 0)
            elif x == 0:
                max_path_sum[x] = max_path_sum[x] + grid_values[y][2]
                paths[y][x] = (0, paths[y][x-1])
            else:
                # Update max_path_sum
                max_path_sum[x] = max(max_path_sum[x-1], max_path_sum[x]) + grid_values[y][2]

                # Determine the previous path
                if max_path_sum[x-1] >= max_path_sum[x]:
                    prev_x, prev_y = paths[y-1][x]
                else:
                    prev_x, prev_y = paths[y][x-1]

                # Update paths
                paths[y][x] = (prev_x, prev_y)

    # Find the maximum by keeping track of the best path sum and its index
    best_path_sum = 0
    best_path = (0, 0)
    for y in range(N):
        for x in range(N):
            if max_path_sum[x] > best_path_sum:
                best_path_sum = max_path_sum[x]
                best_path = (x, y)

    return best_path_sum

