def verify_isbn(isbn: str) -> str:
    if len(isbn) not in [10, 13):
        raise ValueError("Expected ISBN to be either 10 or 13 digits long")

    if isbn[9].isdigit():
        # 10-digit ISBN
        check_digit = 10 - (int(isbn[:9]) % 11)
        if check_digit == 10:
            check_digit = 'X'

        if check_digit != isbn[9]:
            return isbn[:9] + check_digit
        else:
            return "Right"
    else:
        # 13-digit ISBN
        prime_sum = sum(int(digit) * prime for digit, prime in zip(isbn[:-1], [1, 3, 1, 7, 3, 1, 7, 3, 1]))
        check_digit = (11 - (prime_sum % 11)) % 11
        if check_digit == 10:
            check_digit = 'X'

        if check_digit != isbn[12]:
            return isbn[:12] + check_digit
        else:
            return "Right"

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
