    for _ in range(K):
        # Add horizontal aisle
        x = np.random.randint(0, M)
        aisles.add((x, 0))
        aisles.add((x, N))
    for _ in range(L):
        # Add vertical aisle
        y = np.random.randint(0, N)
        aisles.add((0, y))
        aisles.add((M, y))

    max_separate_pairs = 0
    optimal_separation = ('-', '-')
    for i, j in aisles:
        for r, c in aisles:
