def count_passing_ways(n: int, m: int) -> int:
    # Base case: if there are no students, or m passes, there is a single way
    if n == 0 or m == 0:
        return 1

    # Initialize a table to store the number of ways
    dp = [[0 for _ in range(m + 1)] for _ in range(n + 1)]

    # Set up the first row and first column
    for i in range(n + 1):
        dp[i][0] = 1
    for j in range(m + 1):
        dp[0][j] = 0

    # Fill the dynamic programming table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            dp[i][j] = dp[i - 1][j - 1] + dp[i - 2][j - 1]

    # The result is the number of ways after n-1 passes
    return dp[n][m]

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    if n == 0:
        return ""
    res = []
    for i in range(n):
        coeff = coeffs[i]
        if coeff == 0:
            continue
        var_part = ""
        if coeff != 1 and i > 0:
            var_part = f"x^{i}" if i > 1 else f"x"
        sign = "+" if i > 0 else ""
        abs_coeff = abs(coeff)
        if abs_coeff == 1:
            abs_coeff = ""
        res.append(f"{sign}{abs_coeff}{var_part}")
    return "".join(res)

def decode(encoded, original, message):
    # Ensure both encoded and original strings are the same length
    if len(encoded) != len(original):
        return "Failed"

    # Initialize an empty dictionary to store the mapping from encoded to original letters
    encoded_to_original_mapping = {}

    # Build the mapping by matching each encoded letter with its corresponding original letter
    for i in range(len(encoded)):
        if encoded[i] not in encoded_to_original_mapping:
            encoded_to_original_mapping[encoded[i]] = original[i]
        elif encoded_to_original_mapping[encoded[i]] != original[i]:
            return "Failed"

    # Decode the message using the mapping
    decoded_message = ""
    for letter in message:
        if letter in encoded_to_original_mapping:
            decoded_message += encoded_to_original_mapping[letter]
        else:
            return "Failed"

    return decoded_message

def count_sequences(n: int, last: int, memo: dict) -> int:
    if (n, last) not in memo:
        # Base case: A sequence with only the starting number is valid
        if last == -1 or last == 0:
            memo[(n, last)] = 1
        else:
            # Recursive case: Calculate the number of valid sequences
            memo[(n, last)] = count_sequences(n, last // 2, memo) + count_sequences(n + 1, last - 1, memo) if last % 2 == 0 else 0
    return memo[(n, last)]

